static int sas_rediscover(struct domain_device *dev, const int phy_id)
{
	struct expander_device *ex = &dev->ex_dev;
	struct ex_phy *changed_phy = &ex->ex_phy[phy_id];
	int res = 0;
	int i;
	bool last = true;	/* is this the last phy of the port */

	SAS_DPRINTK("ex %016llx phy%d originated BROADCAST(CHANGE)\n",
		    SAS_ADDR(dev->sas_addr), phy_id);

	if (SAS_ADDR(changed_phy->attached_sas_addr) != 0) {
		for (i = 0; i < ex->num_phys; i++) {
			struct ex_phy *phy = &ex->ex_phy[i];

			if (i == phy_id)
				continue;
			if (SAS_ADDR(phy->attached_sas_addr) ==
			    SAS_ADDR(changed_phy->attached_sas_addr)) {
				SAS_DPRINTK("phy%d part of wide port with "
					    "phy%d\n", phy_id, i);
				last = false;
				break;
			}
		}
		res = sas_rediscover_dev(dev, phy_id, last);
	} else
		res = sas_discover_new(dev, phy_id);
	return res;
}

void Parser::read_bom()
{
  size_t skip = 0;
  std::string encoding;
  bool utf_8 = false;
  switch ((unsigned char) source[0]) {
  case 0xEF:
    skip = check_bom_chars(source, end, utf_8_bom, 3);
    encoding = "UTF-8";
    utf_8 = true;
    break;
  case 0xFE:
    skip = check_bom_chars(source, end, utf_16_bom_be, 2);
    encoding = "UTF-16 (big endian)";
    break;
  case 0xFF:
    skip = check_bom_chars(source, end, utf_16_bom_le, 2);
    skip += (skip ? check_bom_chars(source, end, utf_32_bom_le, 4) : 0);
    encoding = (skip == 2 ? "UTF-16 (little endian)" : "UTF-32 (little endian)");
    break;
  case 0x00:
    skip = check_bom_chars(source, end, utf_32_bom_be, 4);
    encoding = "UTF-32 (big endian)";
    break;
  case 0x2B:
    skip = check_bom_chars(source, end, utf_7_bom_1, 4)
         | check_bom_chars(source, end, utf_7_bom_2, 4)
         | check_bom_chars(source, end, utf_7_bom_3, 4)
         | check_bom_chars(source, end, utf_7_bom_4, 4)
         | check_bom_chars(source, end, utf_7_bom_5, 5);
    encoding = "UTF-7";
    break;
  case 0xF7:
    skip = check_bom_chars(source, end, utf_1_bom, 3);
    encoding = "UTF-1";
    break;
  case 0xDD:
    skip = check_bom_chars(source, end, utf_ebcdic_bom, 4);
    encoding = "UTF-EBCDIC";
    break;
  case 0x0E:
    skip = check_bom_chars(source, end, scsu_bom, 3);
    encoding = "SCSU";
    break;
  case 0xFB:
    skip = check_bom_chars(source, end, bocu_1_bom, 3);
    encoding = "BOCU-1";
    break;
  case 0x84:
    skip = check_bom_chars(source, end, gb_18030_bom, 4);
    encoding = "GB-18030";
    break;
  default: break;
  }
  if (skip > 0 && !utf_8) error("only UTF-8 documents are currently supported; your document appears to be " + encoding);
  position += skip;
}

GF_EXPORT
GF_ISOTrackID gf_isom_get_highest_track_in_scalable_segment(GF_ISOFile *movie, u32 for_base_track)
{
#ifdef	GPAC_DISABLE_ISOM_FRAGMENTS
	return 0;
#else
	s32 max_ref;
	u32 i, j;
	GF_ISOTrackID track_id;

	max_ref = 0;
	track_id = 0;
	for (i=0; i<gf_list_count(movie->moov->trackList); i++) {
		s32 ref;
		u32 ref_type = GF_ISOM_REF_SCAL;
		GF_TrackBox *trak = (GF_TrackBox*)gf_list_get(movie->moov->trackList, i);
		if (! trak->present_in_scalable_segment) continue;

		ref = gf_isom_get_reference_count(movie, i+1, ref_type);
		if (ref<=0) {
			//handle implicit reconstruction for LHE1/LHV1, check sbas track ref
			u32 subtype = gf_isom_get_media_subtype(movie, i+1, 1);
			switch (subtype) {
			case GF_ISOM_SUBTYPE_LHE1:
			case GF_ISOM_SUBTYPE_LHV1:
				ref = gf_isom_get_reference_count(movie, i+1, GF_ISOM_REF_BASE);
				if (ref<=0) continue;
				break;
			default:
				continue;
			}
		}
		if (ref<=max_ref) continue;

		for (j=0; j< (u32) ref; j++) {
			u32 on_track=0;
			gf_isom_get_reference(movie, i+1, GF_ISOM_REF_BASE, j+1, &on_track);
			if (on_track==for_base_track) {
				max_ref = ref;
				track_id = trak->Header->trackID;
			}
		}
	}
	return track_id;
#endif

