LogicalResult matchAndRewrite(TFL::MulOp mul_op,
                              PatternRewriter &rewriter) const override {
  // If we are broadcasting on the lhs then don't fold the multiply as it
  // would increase the amount of compute done by the fully connected op.
  if (mul_op.lhs().getType() != mul_op.getType()) return failure();

  // Mul.
  DenseElementsAttr cst;
  Value constant_val = mul_op.rhs();
  if (!matchPattern(constant_val, m_Constant(&cst))) return failure();

  // Fully Connected.
  auto fc_op =
      dyn_cast_or_null<TFL::FullyConnectedOp>(mul_op.lhs().getDefiningOp());
  if (!fc_op) return failure();
  Value filter = fc_op.filter();
  Value bias = fc_op.bias();
  ElementsAttr cst_tmp;
  if (!matchPattern(filter, m_Constant(&cst_tmp))) return failure();
  if (!bias.getType().isa<NoneType>() &&
      !matchPattern(bias, m_Constant(&cst_tmp)))
    return failure();
  if (fc_op.fused_activation_function() != "NONE") return failure();

  // Only fuse multiplier if all dimensions other than the depth dimension
  // are equal to 1 since otherwise
  // `matmul(x, filter) * cst != matmul(x, filter * cst)`
  // even if `filter` and `cst` are be broadcastable.
  auto shape = cst.getType().getShape();
  if (!IsDimensionsDegenerateExceptLastOne(shape)) return failure();

  int64_t element_size = shape.empty() ? 1 : shape[shape.size() - 1];
  // Expand and transpose the multiplier since weights are using the
  // OHWI data format in TFLite.
  int64_t normalized_shape[2] = {element_size, 1};
  auto new_cst = cst.reshape(RankedTensorType::get(
      normalized_shape, cst.getType().getElementType()));
  Type new_type = new_cst.getType();
  if (!IsBroadcastableElementsAttrAndType(new_type, filter.getType())) {
    return failure();
  }

  auto new_op =
      rewriter.create<ConstantOp>(mul_op.getLoc(), new_type, new_cst);
  Value new_const_val = new_op.getResult();

  // Rewrite. Since the folder of TFL::MulOp couldn't broadcast the operands,
  // TF::MulOp is used to fold the constant.
  // TODO(b/139192933): switch to the TFL constant folding
  auto new_filter =
      rewriter.create<TF::MulOp>(mul_op.getLoc(), filter, new_const_val).z();
  // If bias isn't None, it needs to be multiplied as well.
  if (!bias.getType().isa<NoneType>()) {
    bias =
        rewriter.create<TF::MulOp>(mul_op.getLoc(), bias, constant_val).z();
  }

  auto fc = rewriter.create<TFL::FullyConnectedOp>(
      FusedLoc::get(fc_op.getContext(), {fc_op.getLoc(), mul_op.getLoc()}),
      mul_op.getType(),
      /*input=*/fc_op.input(),
      /*filter=*/new_filter,
      /*bias=*/bias,
      /*fused_activation_function=*/
      rewriter.getStringAttr(mul_op.fused_activation_function()),
      /*weights_format=*/rewriter.getStringAttr(fc_op.weights_format()),
      /*keep_num_dims=*/rewriter.getBoolAttr(fc_op.keep_num_dims()));
  rewriter.replaceOp(mul_op, fc.output());

  return success();
}

void LibRaw::parseSonySRF(unsigned len)
{

  if ((len > 0xfffff) || (len == 0))
    return;

  INT64 save = ftell(ifp);
  INT64 offset =
      0x0310c0 - save; /* for non-DNG this value normally is 0x8ddc */
  if (len < offset || offset < 0)
    return;
  INT64 decrypt_len = offset >> 2; /* master key offset value is the next
                                      un-encrypted metadata field after SRF0 */

  unsigned i, nWB;
  unsigned MasterKey, SRF2Key, RawDataKey;
  INT64 srf_offset, tag_offset, tag_data, tag_dataoffset;
  int tag_dataunitlen;
  uchar *srf_buf;
  short entries;
  unsigned tag_id, tag_type, tag_datalen;

  srf_buf = (uchar *)malloc(len);
  fread(srf_buf, len, 1, ifp);

  offset += srf_buf[offset] << 2;

#define CHECKBUFFER_SGET4(offset)                                              \
  do                                                                           \
  {                                                                            \
    if ((((offset) + 4) > len) || ((offset) < 0))                              \
      goto restore_after_parseSonySRF;                                         \
  } while (0)

#define CHECKBUFFER_SGET2(offset)                                              \
  do                                                                           \
  {                                                                            \
    if ( ((offset + 2) > len) || ((offset) < 0))                               \
      goto restore_after_parseSonySRF;                                         \
  } while (0)

  CHECKBUFFER_SGET4(offset);

  /* master key is stored in big endian */
  MasterKey = ((unsigned)srf_buf[offset] << 24) |
              ((unsigned)srf_buf[offset + 1] << 16) |
              ((unsigned)srf_buf[offset + 2] << 8) |
              (unsigned)srf_buf[offset + 3];

  /* skip SRF0 */
  srf_offset = 0;
  CHECKBUFFER_SGET2(srf_offset);
  entries = sget2(srf_buf + srf_offset);
  if (entries > 1000)
    goto restore_after_parseSonySRF;
  offset = srf_offset + 2;
  CHECKBUFFER_SGET4(offset);
  CHECKBUFFER_SGET4(offset + 12 * entries);
  srf_offset = sget4(srf_buf + offset + 12 * entries) -
               save; /* SRF0 ends with SRF1 abs. position */

  /* get SRF1, it has fixed 40 bytes length and contains keys to decode metadata
   * and raw data */
  if (srf_offset < 0 || decrypt_len < srf_offset / 4)
    goto restore_after_parseSonySRF;
  sony_decrypt((unsigned *)(srf_buf + srf_offset), decrypt_len - srf_offset / 4,
               1, MasterKey);
  CHECKBUFFER_SGET2(srf_offset);
  entries = sget2(srf_buf + srf_offset);
  if (entries > 1000)
    goto restore_after_parseSonySRF;
  offset = srf_offset + 2;
  tag_offset = offset;

  while (entries--) {
    if (tiff_sget (save, srf_buf, len,
                   &tag_offset, &tag_id, &tag_type, &tag_dataoffset,
                   &tag_datalen, &tag_dataunitlen) == 0) {
      if (tag_id == 0x0000) {
        SRF2Key = sget4(srf_buf + tag_dataoffset);
      } else if (tag_id == 0x0001) {
        RawDataKey = sget4(srf_buf + tag_dataoffset);
      }
    } else goto restore_after_parseSonySRF;
  }
  offset = tag_offset;

  /* get SRF2 */
  CHECKBUFFER_SGET4(offset);
  srf_offset =
      sget4(srf_buf + offset) - save; /* SRFn ends with SRFn+1 position */
  if (srf_offset < 0 || decrypt_len < srf_offset / 4)
    goto restore_after_parseSonySRF;
  sony_decrypt((unsigned *)(srf_buf + srf_offset), decrypt_len - srf_offset / 4,
               1, SRF2Key);
  CHECKBUFFER_SGET2(srf_offset);
  entries = sget2(srf_buf + srf_offset);
  if (entries > 1000)
    goto restore_after_parseSonySRF;
  offset = srf_offset + 2;
  tag_offset = offset;

  while (entries--) {
    if (tiff_sget (save, srf_buf, len,
                   &tag_offset, &tag_id, &tag_type, &tag_dataoffset,
                   &tag_datalen, &tag_dataunitlen) == 0) {
      if ((tag_id >= 0x00c0) && (tag_id <= 0x00ce)) {
        i = (tag_id - 0x00c0) % 3;
        nWB = (tag_id - 0x00c0) / 3;
        icWBC[Sony_SRF_wb_list[nWB]][i] = sget4(srf_buf + tag_dataoffset);
        if (i == 1) {
          icWBC[Sony_SRF_wb_list[nWB]][3] =
            icWBC[Sony_SRF_wb_list[nWB]][i];
        }
      } else if ((tag_id >= 0x00d0) && (tag_id <= 0x00d2)) {
        i = (tag_id - 0x00d0) % 3;
        cam_mul[i] = sget4(srf_buf + tag_dataoffset);
        if (i == 1) {
          cam_mul[3] = cam_mul[i];
        }
      } else switch (tag_id) {
        /*
        0x0002  SRF6Offset
        0x0003  SRFDataOffset (?)
        0x0004  RawDataOffset
        0x0005  RawDataLength
        */
      case 0x0043:
        ilm.MaxAp4MaxFocal = sgetreal(tag_type, srf_buf + tag_dataoffset);
        break;
      case 0x0044:
         ilm.MaxAp4MinFocal = sgetreal(tag_type, srf_buf + tag_dataoffset);
        break;
      case 0x0045:
        ilm.MinFocal = sgetreal(tag_type, srf_buf + tag_dataoffset);
        break;
      case 0x0046:
        ilm.MaxFocal = sgetreal(tag_type, srf_buf + tag_dataoffset);
        break;
      }
    } else goto restore_after_parseSonySRF;
  }
  offset = tag_offset;

restore_after_parseSonySRF:
  free(srf_buf);
  fseek(ifp, save, SEEK_SET);
#undef CHECKBUFFER_SGET4
#undef CHECKBUFFER_SGET2
}

static int sha1_final(struct shash_desc *desc, u8 *out)
{
	struct sha1_state *sctx = shash_desc_ctx(desc);
	unsigned int i, index, padlen;
	__be32 *dst = (__be32 *)out;
	__be64 bits;
	static const u8 padding[SHA1_BLOCK_SIZE] = { 0x80, };

	bits = cpu_to_be64(sctx->count << 3);

	/* Pad out to 56 mod 64 and append length */
	index = sctx->count % SHA1_BLOCK_SIZE;
	padlen = (index < 56) ? (56 - index) : ((SHA1_BLOCK_SIZE+56) - index);
	/* We need to fill a whole block for __sha1_update() */
	if (padlen <= 56) {
		sctx->count += padlen;
		memcpy(sctx->buffer + index, padding, padlen);
	} else {
		__sha1_update(sctx, padding, padlen, index);
	}
	__sha1_update(sctx, (const u8 *)&bits, sizeof(bits), 56);

	/* Store state in digest */
	for (i = 0; i < 5; i++)
		dst[i] = cpu_to_be32(sctx->state[i]);

	/* Wipe context */
	memset(sctx, 0, sizeof(*sctx));
	return 0;
}

static void bnx2x_drv_info_iscsi_stat(struct bnx2x *bp)
{
