void Compute(OpKernelContext* ctx) override {
  auto value = ctx->input(0);
  auto update = ctx->input(1);

  OP_REQUIRES(
      ctx, value.dims() == update.dims(),
      errors::InvalidArgument("value and update shape doesn't match: ",
                              value.shape().DebugString(), " vs. ",
                              update.shape().DebugString()));
  for (int i = 1; i < value.dims(); ++i) {
    OP_REQUIRES(
        ctx, value.dim_size(i) == update.dim_size(i),
        errors::InvalidArgument("value and update shape doesn't match ",
                                value.shape().DebugString(), " vs. ",
                                update.shape().DebugString()));
  }
  OP_REQUIRES(ctx, 1 == update.dim_size(0),
              errors::InvalidArgument("update shape doesn't match: ",
                                      update.shape().DebugString()));

  Tensor output = value;  // This creates an alias intentionally.
  const auto& d = ctx->eigen_device<Device>();
  OP_REQUIRES_OK(
      ctx, ::tensorflow::functor::DoParallelConcat(d, update, loc_, &output));
  ctx->set_output(0, output);
}

static int get_vmx_mem_address(struct kvm_vcpu *vcpu,
				 unsigned long exit_qualification,
				 u32 vmx_instruction_info, bool wr, gva_t *ret)
{
	gva_t off;
	bool exn;
	struct kvm_segment s;

	/*
	 * According to Vol. 3B, "Information for VM Exits Due to Instruction
	 * Execution", on an exit, vmx_instruction_info holds most of the
	 * addressing components of the operand. Only the displacement part
	 * is put in exit_qualification (see 3B, "Basic VM-Exit Information").
	 * For how an actual address is calculated from all these components,
	 * refer to Vol. 1, "Operand Addressing".
	 */
	int  scaling = vmx_instruction_info & 3;
	int  addr_size = (vmx_instruction_info >> 7) & 7;
	bool is_reg = vmx_instruction_info & (1u << 10);
	int  seg_reg = (vmx_instruction_info >> 15) & 7;
	int  index_reg = (vmx_instruction_info >> 18) & 0xf;
	bool index_is_valid = !(vmx_instruction_info & (1u << 22));
	int  base_reg       = (vmx_instruction_info >> 23) & 0xf;
	bool base_is_valid  = !(vmx_instruction_info & (1u << 27));

	if (is_reg) {
		kvm_queue_exception(vcpu, UD_VECTOR);
		return 1;
	}

	/* Addr = segment_base + offset */
	/* offset = base + [index * scale] + displacement */
	off = exit_qualification; /* holds the displacement */
	if (base_is_valid)
		off += kvm_register_read(vcpu, base_reg);
	if (index_is_valid)
		off += kvm_register_read(vcpu, index_reg)<<scaling;
	vmx_get_segment(vcpu, &s, seg_reg);
	*ret = s.base + off;

	if (addr_size == 1) /* 32 bit */
		*ret &= 0xffffffff;

	/* Checks for #GP/#SS exceptions. */
	exn = false;
	if (is_long_mode(vcpu)) {
		/* Long mode: #GP(0)/#SS(0) if the memory address is in a
		 * non-canonical form. This is the only check on the memory
		 * destination for long mode!
		 */
		exn = is_noncanonical_address(*ret, vcpu);
	} else if (is_protmode(vcpu)) {
		/* Protected mode: apply checks for segment validity in the
		 * following order:
		 * - segment type check (#GP(0) may be thrown)
		 * - usability check (#GP(0)/#SS(0))
		 * - limit check (#GP(0)/#SS(0))
		 */
		if (wr)
			/* #GP(0) if the destination operand is located in a
			 * read-only data segment or any code segment.
			 */
			exn = ((s.type & 0xa) == 0 || (s.type & 8));
		else
			/* #GP(0) if the source operand is located in an
			 * execute-only code segment
			 */
			exn = ((s.type & 0xa) == 8);
		if (exn) {
			kvm_queue_exception_e(vcpu, GP_VECTOR, 0);
			return 1;
		}
		/* Protected mode: #GP(0)/#SS(0) if the segment is unusable.
		 */
		exn = (s.unusable != 0);
		/* Protected mode: #GP(0)/#SS(0) if the memory
		 * operand is outside the segment limit.
		 */
		exn = exn || (off + sizeof(u64) > s.limit);
	}
	if (exn) {
		kvm_queue_exception_e(vcpu,
				      seg_reg == VCPU_SREG_SS ?
						SS_VECTOR : GP_VECTOR,
				      0);
		return 1;
	}

	return 0;
}

void WebUIExtension::Send(gin::Arguments* args) {
  blink::WebLocalFrame* frame;
  RenderFrame* render_frame;
  if (!ShouldRespondToRequest(&frame, &render_frame))
    return;

  std::string message;
  if (!args->GetNext(&message)) {
    args->ThrowError();
    return;
  }

  if (base::EndsWith(message, "RequiringGesture",
                     base::CompareCase::SENSITIVE) &&
      !blink::WebUserGestureIndicator::IsProcessingUserGesture(frame)) {
    NOTREACHED();
    return;
  }

  std::unique_ptr<base::ListValue> content;
  if (args->PeekNext().IsEmpty() || args->PeekNext()->IsUndefined()) {
    content.reset(new base::ListValue());
  } else {
    v8::Local<v8::Object> obj;
    if (!args->GetNext(&obj)) {
      args->ThrowError();
      return;
    }

     content = base::ListValue::From(V8ValueConverter::Create()->FromV8Value(
         obj, frame->MainWorldScriptContext()));
     DCHECK(content);
   }

  render_frame->Send(new FrameHostMsg_WebUISend(render_frame->GetRoutingID(),
                                                frame->GetDocument().Url(),
                                                message, *content));
}

void Compute(OpKernelContext* ctx) override {
  StagingMap<Ordered>* map = nullptr;
  OP_REQUIRES_OK(ctx, GetStagingMap(ctx, def(), &map));
  core::ScopedUnref scope(map);
  typename StagingMap<Ordered>::OptionalTuple tuple;

  const Tensor* key_tensor;
  const Tensor* indices_tensor;
  OpInputList values_tensor;

  OP_REQUIRES_OK(ctx, ctx->input("key", &key_tensor));
  OP_REQUIRES_OK(ctx, ctx->input("indices", &indices_tensor));
  OP_REQUIRES_OK(ctx, ctx->input_list("values", &values_tensor));
  OP_REQUIRES(ctx, key_tensor->NumElements() > 0,
              errors::InvalidArgument("key must not be empty"));

  // Create copy for insertion into Staging Area
  Tensor key(*key_tensor);

  // Create the tuple to store
  for (std::size_t i = 0; i < values_tensor.size(); ++i) {
    tuple.push_back(values_tensor[i]);
  }

  // Store the tuple in the map
  OP_REQUIRES_OK(ctx, map->put(&key, indices_tensor, &tuple));
}

