int readDataVar(struct READER *reader, struct DATAOBJECT *data,
                struct DATATYPE *dt, struct DATASPACE *ds) {

  char *buffer, number[20];
  uint64_t reference, gcol = 0, dataobject;
  int err;
  struct DATAOBJECT *referenceData;

  if (dt->list) {
    if (dt->list - dt->size == 8) {
      readValue(reader, 4); /* TODO unknown? */
      gcol = readValue(reader, 4);
    } else {
      gcol = readValue(reader, dt->list - dt->size);
    }
    mylog("    GCOL %d %8" PRIX64 " %8lX\n", dt->list - dt->size, gcol,
          ftell(reader->fhd));
    /*		fseek(reader->fhd, dt->list - dt->size, SEEK_CUR); TODO:
     * TODO: missing part in specification */
  }

  switch (dt->class_and_version & 0xf) {
  case 0:
    mylog("FIXED POINT todo %lX %d\n", ftell(reader->fhd), dt->size);
    if (fseek(reader->fhd, dt->size, SEEK_CUR))
      return errno; // LCOV_EXCL_LINE
    break;

  case 3:
    buffer = malloc(dt->size + 1);
    if (buffer == NULL) {
      return MYSOFA_NO_MEMORY; // LCOV_EXCL_LINE
    }
    if (fread(buffer, 1, dt->size, reader->fhd) != dt->size) {
      free(buffer);             // LCOV_EXCL_LINE
      return MYSOFA_READ_ERROR; // LCOV_EXCL_LINE
    }
    buffer[dt->size] = 0;
    mylog("STRING %s\n", buffer);
    data->string = buffer;
    break;

    /*
     * 000036e3   67 0e 00 00 00  00 00 00 00 00 00 00 00  |...g............|
     000036f0  00 00 00
     */
  case 6:
    /* TODO unclear spec */
    mylog("COMPONENT todo %lX %d\n", ftell(reader->fhd), dt->size);
    if (fseek(reader->fhd, dt->size, SEEK_CUR))
      return errno; // LCOV_EXCL_LINE
    break;

  case 7:
    readValue(reader, 4); /* TODO unclear reference */
    reference = readValue(reader, dt->size - 4);
    mylog(" REFERENCE size %d %" PRIX64 "\n", dt->size, reference);
    if (!!(err = gcolRead(reader, gcol, reference, &dataobject))) {
      return MYSOFA_OK; /* ignore error. TODO: why?
       return err; */
    }
    referenceData = findDataobject(reader, dataobject);
    if (referenceData)
      buffer = referenceData->name;
    else {
      sprintf(number, "REF%08lX", (long unsigned int)reference);
      buffer = number;
    }
    mylog("    REFERENCE %" PRIX64 " %" PRIX64 " %s\n", reference, dataobject,
          buffer);
    /*		if(!referenceData) { TODO?
     return MYSOFA_UNSUPPORTED_FORMAT;
     } */
    if (data->string) {
      data->string =
          realloc(data->string, strlen(data->string) + strlen(buffer) + 2);
      if (!data->string)
        return MYSOFA_NO_MEMORY;
      strcat(data->string, ",");
      strcat(data->string, buffer);
    } else {
      data->string = mysofa_strdup(buffer);
    }
    break;

  default:
    // LCOV_EXCL_START
    mylog("data reader unknown type %d\n", dt->class_and_version & 0xf);
    return MYSOFA_INTERNAL_ERROR;
    // LCOV_EXCL_STOP
  }
  return MYSOFA_OK;
}

static void AppLayerProtoDetectFreeProbingParsers(AppLayerProtoDetectProbingParser *pp)
{
    SCEnter();

    AppLayerProtoDetectProbingParser *tmp_pp = NULL;

    if (pp == NULL)
        goto end;

    while (pp != NULL) {
        tmp_pp = pp->next;
        AppLayerProtoDetectProbingParserFree(pp);
        pp = tmp_pp;
    }

 end:
    SCReturn;
}

MONGO_EXPORT double mongo_count( mongo *conn, const char *db, const char *ns, const bson *query ) {
    bson cmd;
    bson out = {NULL, 0};
    double count = -1;

    bson_init( &cmd );
    bson_append_string( &cmd, "count", ns );
    if ( query && bson_size( query ) > 5 ) /* not empty */
        bson_append_bson( &cmd, "query", query );
    bson_finish( &cmd );

    if( mongo_run_command( conn, db, &cmd, &out ) == MONGO_OK ) {
        bson_iterator it;
        if( bson_find( &it, &out, "n" ) )
            count = bson_iterator_double( &it );
        bson_destroy( &cmd );
        bson_destroy( &out );
        return count;
    }
    else {
        bson_destroy( &out );
        bson_destroy( &cmd );
        return MONGO_ERROR;
    }
}

static RList *symbols(RBinFile *bf) {
	RList *res = r_list_newf ((RListFree)r_bin_symbol_free);
	r_return_val_if_fail (res && bf->o && bf->o->bin_obj, res);
	RCoreSymCacheElement *element = bf->o->bin_obj;
	size_t i;
	HtUU *hash = ht_uu_new0 ();
	if (!hash) {
		return res;
	}
	bool found = false;
	for (i = 0; i < element->hdr->n_lined_symbols; i++) {
		RCoreSymCacheElementSymbol *sym = (RCoreSymCacheElementSymbol *)&element->lined_symbols[i];
		ht_uu_find (hash, sym->paddr, &found);
		if (found) {
			continue;
		}
		RBinSymbol *s = bin_symbol_from_symbol (element, sym);
		if (s) {
			r_list_append (res, s);
			ht_uu_insert (hash, sym->paddr, 1);
		}
	}
	if (element->symbols) {
		for (i = 0; i < element->hdr->n_symbols; i++) {
			RCoreSymCacheElementSymbol *sym = &element->symbols[i];
			ht_uu_find (hash, sym->paddr, &found);
			if (found) {
				continue;
			}
			RBinSymbol *s = bin_symbol_from_symbol (element, sym);
			if (s) {
				r_list_append (res, s);
			}
		}
	}
	ht_uu_free (hash);
	return res;
}

void Compute(OpKernelContext* context) override {
  const Tensor& x = context->input(0);
  const Tensor& y = context->input(1);
  const float min_x = context->input(2).flat<float>()(0);
  const float max_x = context->input(3).flat<float>()(0);
  const float min_y = context->input(4).flat<float>()(0);
  const float max_y = context->input(5).flat<float>()(0);

  BCast bcast(BCast::FromShape(x.shape()), BCast::FromShape(y.shape()));
  if (!bcast.IsValid()) {
    context->SetStatus(errors::InvalidArgument(
        "Incompatible shapes: ", x.shape().DebugString(), " vs. ",
        y.shape().DebugString()));
    return;
  }
  Tensor* z;
  OP_REQUIRES_OK(context, context->allocate_output(
                              0, BCast::ToShape(bcast.output_shape()), &z));

  // Make sure that we have valid quantization ranges for the input buffers.
  // If the difference between the min and max is negative or zero, it makes
  // it hard to do meaningful intermediate operations on the values.
  OP_REQUIRES(context, (max_x > min_x),
              errors::InvalidArgument("max_x must be larger than min_x."));
  OP_REQUIRES(context, (max_y > min_y),
              errors::InvalidArgument("max_y must be larger than min_y."));
  const T* x_data = x.flat<T>().data();
  const T* y_data = y.flat<T>().data();
  Toutput* z_data = z->flat<Toutput>().data();

  // We want the range of the output to be symmetrical around zero so that
  // adding zero leaves the result unchanged, and to contain the largest of
  // the two input values with some room to spare.
  const float smallest_min = std::min(min_x, min_y);
  const float largest_max = std::max(max_x, max_y);
  const float biggest_range =
      std::max(std::abs(smallest_min), std::abs(largest_max));
  const float output_range = (biggest_range * (1 << 14));
  const float min_z_value = -output_range;
  const float max_z_value = output_range;

  const int ndims = bcast.x_reshape().size();
  if (ndims <= 1) {
    if (x.NumElements() == 1) {
      ScalarAddition<T, Toutput>(context, y_data, min_y, max_y,
                                 y.NumElements(), x_data[0], min_x, max_x,
                                 min_z_value, max_z_value, z_data);
    } else if (y.NumElements() == 1) {
      ScalarAddition<T, Toutput>(context, x_data, min_x, max_x,
                                 x.NumElements(), y_data[0], min_y, max_y,
                                 min_z_value, max_z_value, z_data);
    } else {
      VectorAddition<T, Toutput>(context, x_data, min_x, max_x, y_data, min_y,
                                 max_y, x.NumElements(), min_z_value,
                                 max_z_value, z_data);
    }
  } else if (ndims == 2) {
    const T* vector_data;
    int64 vector_num_elements;
    float vector_min;
    float vector_max;
    const T* tensor_data;
    int64 tensor_num_elements;
    float tensor_min;
    float tensor_max;
    if (x.NumElements() < y.NumElements()) {
      vector_data = x_data;
      vector_num_elements = x.NumElements();
      vector_min = min_x;
      vector_max = max_x;
      tensor_data = y_data;
      tensor_num_elements = y.NumElements();
      tensor_min = min_y;
      tensor_max = max_y;
    } else {
      vector_data = y_data;
      vector_num_elements = y.NumElements();
      vector_min = min_y;
      vector_max = max_y;
      tensor_data = x_data;
      tensor_num_elements = x.NumElements();
      tensor_min = min_x;
      tensor_max = max_x;
    }
    VectorTensorAddition<T, Toutput>(
        vector_data, vector_min, vector_max, vector_num_elements, tensor_data,
        tensor_min, tensor_max, tensor_num_elements, min_z_value, max_z_value,
        z_data);
  } else {
    LOG(INFO) << "ndims=" << ndims;
    LOG(INFO) << "bcast.x_reshape()="
              << TensorShape(bcast.x_reshape()).DebugString();
    LOG(INFO) << "bcast.y_reshape()="
              << TensorShape(bcast.y_reshape()).DebugString();
    LOG(INFO) << "bcast.x_bcast()="
              << TensorShape(bcast.x_bcast()).DebugString();
    LOG(INFO) << "bcast.y_bcast()="
              << TensorShape(bcast.y_bcast()).DebugString();

    context->SetStatus(errors::Unimplemented(
        "Broadcast between ", context->input(0).shape().DebugString(),
        " and ", context->input(1).shape().DebugString(),
        " is not supported yet."));
    return;
  }

  Tensor* z_min = nullptr;
  OP_REQUIRES_OK(context, context->allocate_output(1, {}, &z_min));
  z_min->flat<float>()(0) = min_z_value;

  Tensor* z_max = nullptr;
  OP_REQUIRES_OK(context, context->allocate_output(2, {}, &z_max));
  z_max->flat<float>()(0) = max_z_value;
}

static void account_event(struct perf_event *event)
{
	bool inc = false;

	if (event->parent)
		return;

	if (event->attach_state & PERF_ATTACH_TASK)
		inc = true;
	if (event->attr.mmap || event->attr.mmap_data)
		atomic_inc(&nr_mmap_events);
	if (event->attr.comm)
		atomic_inc(&nr_comm_events);
	if (event->attr.namespaces)
		atomic_inc(&nr_namespaces_events);
	if (event->attr.cgroup)
		atomic_inc(&nr_cgroup_events);
	if (event->attr.task)
		atomic_inc(&nr_task_events);
	if (event->attr.freq)
		account_freq_event();
	if (event->attr.context_switch) {
		atomic_inc(&nr_switch_events);
		inc = true;
	}
	if (has_branch_stack(event))
		inc = true;
	if (is_cgroup_event(event))
		inc = true;
	if (event->attr.ksymbol)
		atomic_inc(&nr_ksymbol_events);
	if (event->attr.bpf_event)
		atomic_inc(&nr_bpf_events);
	if (event->attr.text_poke)
		atomic_inc(&nr_text_poke_events);

	if (inc) {
		/*
		 * We need the mutex here because static_branch_enable()
		 * must complete *before* the perf_sched_count increment
		 * becomes visible.
		 */
		if (atomic_inc_not_zero(&perf_sched_count))
			goto enabled;

		mutex_lock(&perf_sched_mutex);
		if (!atomic_read(&perf_sched_count)) {
			static_branch_enable(&perf_sched_events);
			/*
			 * Guarantee that all CPUs observe they key change and
			 * call the perf scheduling hooks before proceeding to
			 * install events that need them.
			 */
			synchronize_rcu();
		}
		/*
		 * Now that we have waited for the sync_sched(), allow further
		 * increments to by-pass the mutex.
		 */
		atomic_inc(&perf_sched_count);
		mutex_unlock(&perf_sched_mutex);
	}
enabled:

	account_event_cpu(event, event->cpu);

	account_pmu_sb_event(event);
}

virtual void ComputeWithReservedSpace(OpKernelContext* context,
                                      bool use_reserved_space) {
  Tensor x = context->input(0);
  const Tensor& scale = context->input(1);
  const Tensor& offset = context->input(2);
  const Tensor& estimated_mean = context->input(3);
  const Tensor& estimated_variance = context->input(4);
  const Tensor* side_input = has_side_input_ ? &context->input(5) : nullptr;

  OP_REQUIRES(context, x.dims() == 4 || x.dims() == 5,
              errors::InvalidArgument("input must be 4 or 5-dimensional",
                                      x.shape().DebugString()));
  OP_REQUIRES(context, scale.dims() == 1,
              errors::InvalidArgument("scale must be 1-dimensional",
                                      scale.shape().DebugString()));
  OP_REQUIRES(context, offset.dims() == 1,
              errors::InvalidArgument("offset must be 1-dimensional",
                                      offset.shape().DebugString()));
  OP_REQUIRES(context, estimated_mean.dims() == 1,
              errors::InvalidArgument("estimated_mean must be 1-dimensional",
                                      estimated_mean.shape().DebugString()));
  OP_REQUIRES(
      context, estimated_variance.dims() == 1,
      errors::InvalidArgument("estimated_variance must be 1-dimensional",
                              estimated_variance.shape().DebugString()));
  bool use_reshape = (x.dims() == 5);
  auto x_shape = x.shape();
  TensorShape dest_shape;
  if (use_reshape) {
    const int64 in_batch = GetTensorDim(x, tensor_format_, 'N');
    int64 in_planes = GetTensorDim(x, tensor_format_, '0');
    int64 in_rows = GetTensorDim(x, tensor_format_, '1');
    int64 in_cols = GetTensorDim(x, tensor_format_, '2');
    const int64 in_depth = GetTensorDim(x, tensor_format_, 'C');
    dest_shape = ShapeFromFormat(tensor_format_, in_batch,
                                 {{in_planes, in_rows * in_cols}}, in_depth);
    OP_REQUIRES(context, x.CopyFrom(x, dest_shape),
                errors::InvalidArgument("Error during tensor copy."));
  }

  if (has_side_input_) {
    OP_REQUIRES(context, side_input->shape() == x.shape(),
                errors::InvalidArgument(
                    "side_input shape must be equal to input shape: ",
                    side_input->shape().DebugString(),
                    " != ", x.shape().DebugString()));
  }

  if (activation_mode_ != FbnActivationMode::kIdentity) {
    // NOTE(ezhulenev): This requirement is coming from implementation
    // details of cudnnBatchNormalizationForwardTrainingEx.
    OP_REQUIRES(
        context, !is_training_ || x.dim_size(3) % 4 == 0,
        errors::InvalidArgument("FusedBatchNorm with activation requires "
                                "channel dimension to be a multiple of 4."));
  }

  Tensor* y = nullptr;
  auto alloc_shape = use_reshape ? dest_shape : x_shape;
  OP_REQUIRES_OK(context, context->forward_input_or_allocate_output(
                              {0}, 0, alloc_shape, &y));

  Tensor* batch_mean = nullptr;
  OP_REQUIRES_OK(context, context->forward_input_or_allocate_output(
                              {3}, 1, scale.shape(), &batch_mean));
  Tensor* batch_var = nullptr;
  OP_REQUIRES_OK(context, context->forward_input_or_allocate_output(
                              {4}, 2, scale.shape(), &batch_var));
  Tensor* saved_mean = nullptr;
  OP_REQUIRES_OK(context,
                 context->allocate_output(3, scale.shape(), &saved_mean));
  Tensor* saved_maybe_inv_var = nullptr;
  OP_REQUIRES_OK(context, context->allocate_output(4, scale.shape(),
                                                   &saved_maybe_inv_var));

  if (is_training_) {
    functor::FusedBatchNorm<Device, T, U, true>()(
        context, x, scale, offset, estimated_mean, estimated_variance,
        side_input, epsilon_, exponential_avg_factor_, activation_mode_, y,
        batch_mean, batch_var, saved_mean, saved_maybe_inv_var,
        tensor_format_, use_reserved_space);
  } else {
    functor::FusedBatchNorm<Device, T, U, false>()(
        context, x, scale, offset, estimated_mean, estimated_variance,
        side_input, epsilon_, exponential_avg_factor_, activation_mode_, y,
        batch_mean, batch_var, saved_mean, saved_maybe_inv_var,
        tensor_format_, use_reserved_space);
  }
  if (use_reshape) {
    OP_REQUIRES(context, y->CopyFrom(*y, x_shape),
                errors::InvalidArgument("Error during tensor copy."));
  }
}

